{
  "schema_version": "sections_v1",
  "chapters": [
    {
      "chapter_id": 1,
      "sections": [
        {
          "section_id": 1,
          "title": "The Exit Interview",
          "intent": "Establish Artie's mundane life and sudden, absurd death.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Artie is locked into the 'Crit or Quit' build with 1 HP and 100% Critical Hit rate."
        },
        {
          "section_id": 2,
          "title": "The First Spawn",
          "intent": "Show the immediate danger of a 1 HP build in a hostile tutorial zone.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Artie is forced to run for his life as the tutorial zone aggros on him."
        },
        {
          "section_id": 3,
          "title": "The Safe Zone?",
          "intent": "Reach the first hub and establish the world's culture and Artie's first rival.",
          "section_role": "transition",
          "target_scene_count": 3,
          "end_condition": "Artie makes his first rival and barely escapes a forced duel."
        }
      ]
    },
    {
      "chapter_id": 2,
      "sections": [
        {
          "section_id": 1,
          "title": "Shopping for Scraps",
          "intent": "Equip Artie with the bare minimum to survive a dungeon through exploitation.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie acquires the 'Cloak of the Cowardly Lion' and looks like a neon yellow cat."
        },
        {
          "section_id": 2,
          "title": "The Crypt of Bad Math",
          "intent": "Test the new gear and the Crit-build in a controlled environment.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "Artie discovers he can farm resources much faster than anyone else via System Overload."
        },
        {
          "section_id": 3,
          "title": "The Rival's Shadow",
          "intent": "Reintroduce Vane as a persistent threat and trigger the boss fight.",
          "section_role": "pressure",
          "target_scene_count": 3,
          "end_condition": "The boss battle begins with Artie at a massive disadvantage against the Bone Golem."
        }
      ]
    },
    {
      "chapter_id": 3,
      "sections": [
        {
          "section_id": 1,
          "title": "The Dance of Death",
          "intent": "A high-octane fight where Artie must dodge every single attack.",
          "section_role": "action",
          "target_scene_count": 3,
          "end_condition": "The floor collapses, trapping the Golem in a hole."
        },
        {
          "section_id": 2,
          "title": "The Final Blow",
          "intent": "Resolve the boss fight with a comedic but effective exploit.",
          "section_role": "climax",
          "target_scene_count": 3,
          "end_condition": "Artie is now Level 10, but the System is watching him more closely."
        },
        {
          "section_id": 3,
          "title": "Looting the Teacups",
          "intent": "Examine the rewards and the consequences of the fight.",
          "section_role": "aftermath",
          "target_scene_count": 4,
          "end_condition": "Artie uses his new level-up speed to outrun Vane's party, heading toward the capital city."
        }
      ]
    },
    {
      "chapter_id": 4,
      "sections": [
        {
          "section_id": 1,
          "title": "The City of Gold and Glitches",
          "intent": "Establish the capital city as a place where 'Crits' are worshiped.",
          "section_role": "setup",
          "target_scene_count": 2,
          "end_condition": "Artie realizes he is stuck with his glass cannon build forever."
        },
        {
          "section_id": 2,
          "title": "The Underground Market",
          "intent": "Artie looks for illegal mods to help him survive.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "Artie escapes the raid, but the potion has a side effect: he speaks in binary for an hour."
        },
        {
          "section_id": 3,
          "title": "The Arena Invitation",
          "intent": "Set up the climax of the book via the tournament entry.",
          "section_role": "escalation",
          "target_scene_count": 3,
          "end_condition": "The stage is set for the final confrontation as Vane prepares to delete Artie."
        }
      ]
    },
    {
      "chapter_id": 5,
      "sections": [
        {
          "section_id": 1,
          "title": "The Round of 32",
          "intent": "Show Artie's growth and tactical use of his crits in the arena.",
          "section_role": "action",
          "target_scene_count": 3,
          "end_condition": "Artie moves to the quarter-finals after winning the second round."
        },
        {
          "section_id": 2,
          "title": "The Quarter-Finals: The Mirror Match",
          "intent": "Artie faces a character with high evasion, just like him.",
          "section_role": "trial",
          "target_scene_count": 4,
          "end_condition": "Artie's next match will have a 'Random Debuff' applied by the System."
        },
        {
          "section_id": 3,
          "title": "The Semi-Finals: The Debuff",
          "intent": "Artie must overcome a mechanical handicap to reach the finals.",
          "section_role": "trial",
          "target_scene_count": 4,
          "end_condition": "Vane watches from the wings, holding a 'System Override' scroll for the final fight."
        }
      ]
    },
    {
      "chapter_id": 6,
      "sections": [
        {
          "section_id": 1,
          "title": "Vane's Ultimate Build",
          "intent": "Show the power of a 'Whale' player vs. a 'Glitch' player.",
          "section_role": "setup",
          "target_scene_count": 4,
          "end_condition": "Artie targets the magic aura around Vane's armor to bypass the reflect buff."
        },
        {
          "section_id": 2,
          "title": "Breaking the Game",
          "intent": "The moment of peak absurdity and power where the world breaks.",
          "section_role": "climax",
          "target_scene_count": 6,
          "end_condition": "They escape the deletion, but the world is now in 'Safe Mode'."
        },
        {
          "section_id": 3,
          "title": "The Aftermath of the Crash",
          "intent": "Show the immediate consequences of the climax.",
          "section_role": "aftermath",
          "target_scene_count": 2,
          "end_condition": "Artie is no longer a player; he is a virus with 'NaN' HP."
        }
      ]
    },
    {
      "chapter_id": 7,
      "sections": [
        {
          "section_id": 1,
          "title": "The New Normal",
          "intent": "Establish the new status quo for Artie and Fizz in the Null-Zone.",
          "section_role": "setup",
          "target_scene_count": 3,
          "end_condition": "Artie realizes his immortality is just as annoying as his 1 HP build."
        },
        {
          "section_id": 2,
          "title": "The Resistance",
          "intent": "Introduce the faction that will help Artie in the future.",
          "section_role": "investigation",
          "target_scene_count": 3,
          "end_condition": "The series arc is locked in with the quest: 'Delete the Admin'."
        },
        {
          "section_id": 3,
          "title": "The First Step",
          "intent": "End on a high note of action and anticipation for the sequel.",
          "section_role": "transition",
          "target_scene_count": 2,
          "end_condition": "Artie steps into a portal, ending Book 1."
        }
      ]
    }
  ]
}

